import type { PlayerStatistics } from '../player/types';

export interface MatchRewardInput {
  rank: number;
  playerCount: number;
  holesPlayed: number;
  holesCompleted: number;
  totalStrokes: number;
  coursePar: number;
  holesInOne: number;
  birdies: number;
  durationSeconds: number;
}

export interface MatchReward {
  xp: number;
  breakdown: {
    completion: number;
    win: number;
    podium: number;
    holesInOne: number;
    birdies: number;
  };
}

export const COMPLETION_XP = 100;
export const WIN_XP = 50;
export const PODIUM_XP = 25;
export const HOLE_IN_ONE_XP = 20;
export const BIRDIE_XP = 10;
export const PODIUM_MIN_PLAYERS = 4;

const finite = (value: number): number => (Number.isFinite(value) ? value : 0);
const count = (value: number): number => Math.max(0, Math.floor(finite(value)));

export function calculateMatchReward(input: MatchRewardInput): MatchReward {
  const rank = count(input.rank);
  const playerCount = count(input.playerCount);
  const win = rank === 1 ? WIN_XP : 0;
  const onPodium = (rank === 2 || rank === 3) && playerCount >= PODIUM_MIN_PLAYERS;
  const podium = win === 0 && onPodium ? PODIUM_XP : 0;
  const holesInOne = count(input.holesInOne) * HOLE_IN_ONE_XP;
  const birdies = count(input.birdies) * BIRDIE_XP;
  const breakdown = { completion: COMPLETION_XP, win, podium, holesInOne, birdies };
  const total = breakdown.completion + breakdown.win + breakdown.podium + breakdown.holesInOne + breakdown.birdies;
  return { xp: Math.max(0, Math.round(total)), breakdown };
}

export function applyMatchStatistics(stats: PlayerStatistics, input: MatchRewardInput): PlayerStatistics {
  const rank = count(input.rank);
  const holesPlayed = count(input.holesPlayed);
  const holesCompleted = count(input.holesCompleted);
  const totalStrokes = count(input.totalStrokes);
  const holesInOne = count(input.holesInOne);
  const duration = Math.max(0, Math.round(finite(input.durationSeconds)));
  const previousBest =
    typeof stats.bestRoundStrokes === 'number' && Number.isFinite(stats.bestRoundStrokes)
      ? stats.bestRoundStrokes
      : null;
  const fullRound = holesPlayed > 0 && holesCompleted === holesPlayed;
  const bestRoundStrokes = fullRound
    ? previousBest === null
      ? totalStrokes
      : Math.min(previousBest, totalStrokes)
    : previousBest;
  return {
    matchesPlayed: count(stats.matchesPlayed) + 1,
    matchesWon: count(stats.matchesWon) + (rank === 1 ? 1 : 0),
    holesPlayed: count(stats.holesPlayed) + holesPlayed,
    holesCompleted: count(stats.holesCompleted) + holesCompleted,
    totalStrokes: count(stats.totalStrokes) + totalStrokes,
    holesInOne: count(stats.holesInOne) + holesInOne,
    bestRoundStrokes,
    totalPlayTimeSeconds: count(stats.totalPlayTimeSeconds) + duration,
  };
}
