import { describe, expect, it } from 'vitest';
import type { PlayerStatistics } from '../player/types';
import { applyMatchStatistics, calculateMatchReward, type MatchRewardInput } from './MatchRewards';

const makeInput = (overrides: Partial<MatchRewardInput> = {}): MatchRewardInput => ({
  rank: 1,
  playerCount: 4,
  holesPlayed: 9,
  holesCompleted: 9,
  totalStrokes: 30,
  coursePar: 27,
  holesInOne: 0,
  birdies: 0,
  durationSeconds: 600,
  ...overrides,
});

const makeStats = (overrides: Partial<PlayerStatistics> = {}): PlayerStatistics => ({
  matchesPlayed: 2,
  matchesWon: 1,
  holesPlayed: 18,
  holesCompleted: 18,
  totalStrokes: 70,
  holesInOne: 1,
  bestRoundStrokes: null,
  totalPlayTimeSeconds: 1200,
  ...overrides,
});

describe('calculateMatchReward', () => {
  it('gives a winner the 150 xp baseline', () => {
    const reward = calculateMatchReward(makeInput());
    expect(reward.xp).toBe(150);
    expect(reward.breakdown).toEqual({ completion: 100, win: 50, podium: 0, holesInOne: 0, birdies: 0 });
  });

  it('applies podium xp only with four or more players', () => {
    expect(calculateMatchReward(makeInput({ rank: 2, playerCount: 4 })).xp).toBe(125);
    expect(calculateMatchReward(makeInput({ rank: 3, playerCount: 4 })).breakdown.podium).toBe(25);
    expect(calculateMatchReward(makeInput({ rank: 2, playerCount: 3 })).xp).toBe(100);
    expect(calculateMatchReward(makeInput({ rank: 4, playerCount: 8 })).breakdown.podium).toBe(0);
  });

  it('keeps win and podium mutually exclusive', () => {
    const reward = calculateMatchReward(makeInput({ rank: 1, playerCount: 8 }));
    expect(reward.breakdown.win).toBe(50);
    expect(reward.breakdown.podium).toBe(0);
  });

  it('adds hole in one and birdie bonuses', () => {
    const reward = calculateMatchReward(makeInput({ rank: 5, playerCount: 8, holesInOne: 2, birdies: 3 }));
    expect(reward.breakdown.holesInOne).toBe(40);
    expect(reward.breakdown.birdies).toBe(30);
    expect(reward.xp).toBe(170);
  });

  it('treats non finite counters as zero and returns an integer', () => {
    const reward = calculateMatchReward(makeInput({ rank: Number.NaN, holesInOne: Number.NaN, birdies: Number.POSITIVE_INFINITY }));
    expect(reward.xp).toBe(100);
    expect(Number.isInteger(reward.xp)).toBe(true);
  });
});

describe('applyMatchStatistics', () => {
  it('does not mutate the input statistics', () => {
    const stats = makeStats();
    const snapshot = { ...stats };
    const next = applyMatchStatistics(stats, makeInput());
    expect(stats).toEqual(snapshot);
    expect(next).not.toBe(stats);
  });

  it('accumulates counters, wins and play time', () => {
    const next = applyMatchStatistics(makeStats(), makeInput({ holesInOne: 1, durationSeconds: 600.4 }));
    expect(next.matchesPlayed).toBe(3);
    expect(next.matchesWon).toBe(2);
    expect(next.holesPlayed).toBe(27);
    expect(next.holesCompleted).toBe(27);
    expect(next.totalStrokes).toBe(100);
    expect(next.holesInOne).toBe(2);
    expect(next.totalPlayTimeSeconds).toBe(1800);
  });

  it('does not increment wins for a non winner', () => {
    const next = applyMatchStatistics(makeStats(), makeInput({ rank: 2 }));
    expect(next.matchesWon).toBe(1);
  });

  it('sets bestRoundStrokes only on a full round', () => {
    const partial = applyMatchStatistics(makeStats(), makeInput({ holesCompleted: 7 }));
    expect(partial.bestRoundStrokes).toBeNull();
    const full = applyMatchStatistics(makeStats(), makeInput());
    expect(full.bestRoundStrokes).toBe(30);
    const empty = applyMatchStatistics(makeStats(), makeInput({ holesPlayed: 0, holesCompleted: 0 }));
    expect(empty.bestRoundStrokes).toBeNull();
  });

  it('keeps the lower bestRoundStrokes value', () => {
    const better = applyMatchStatistics(makeStats({ bestRoundStrokes: 28 }), makeInput({ totalStrokes: 30 }));
    expect(better.bestRoundStrokes).toBe(28);
    const improved = applyMatchStatistics(makeStats({ bestRoundStrokes: 34 }), makeInput({ totalStrokes: 30 }));
    expect(improved.bestRoundStrokes).toBe(30);
    const partial = applyMatchStatistics(makeStats({ bestRoundStrokes: 34 }), makeInput({ totalStrokes: 12, holesCompleted: 4 }));
    expect(partial.bestRoundStrokes).toBe(34);
  });

  it('normalises non finite stored statistics', () => {
    const next = applyMatchStatistics(makeStats({ matchesPlayed: Number.NaN, totalPlayTimeSeconds: Number.NaN }), makeInput({ durationSeconds: Number.NaN }));
    expect(next.matchesPlayed).toBe(1);
    expect(next.totalPlayTimeSeconds).toBe(0);
  });
});
